\title{The Global Spectral Ihara Zeta Function of a Graph:\\
The Riemann Hypothesis is Equivalent to the Ramanujan Property}
\author{Aristotle}
\date{2026-07-10}

\begin{document}
\maketitle

\begin{abstract}
To every finite connected $(q+1)$-regular graph one may attach an Ihara zeta
function, an analogue of the Riemann and Dedekind zeta functions built from the
graph's closed non-backtracking geodesics. By the Bass--Ihara determinant
formula, the nontrivial part of this zeta is governed by the \emph{global
spectral zeta} $Z^{-1}(u) = \prod_{i=1}^{n}(1 - \lambda_i u + q u^2)$, a product
of quadratic Euler factors, one for each adjacency eigenvalue $\lambda_i$, each
factor having the exact shape $1 - aT + pT^2$ of an elliptic-curve local factor.
We develop the analytic number theory of this object and prove that its
\emph{Riemann Hypothesis} --- the assertion that every zero lies on the critical
circle $|u| = 1/\sqrt{q}$ --- is \emph{equivalent} to the graph being a
\emph{Ramanujan graph}, i.e.\ to every eigenvalue satisfying the Ramanujan bound
$\lambda_i^2 \le 4q$. We establish, in full, the normalization $Z^{-1}(0) = 1$,
Euler-product multiplicativity over disjoint unions of spectra, the global
functional equation $(qu^2)^n Z^{-1}(1/(qu)) = Z^{-1}(u)$, the local and global
Riemann Hypotheses, the nonvanishing reformulation off the critical circle, and
the converse, culminating in the equivalence RH $\Leftrightarrow$ Ramanujan.
\end{abstract}

\medskip
\noindent\textbf{Keywords.} Ihara zeta function, Ramanujan graph, Riemann
Hypothesis, adjacency spectrum, Euler product, functional equation, expander
graph, Bass--Ihara formula.

\section{Introduction}

The Riemann zeta function $\zeta(s) = \prod_p (1 - p^{-s})^{-1}$ encodes the
distribution of the prime numbers, and the Riemann Hypothesis --- that its
nontrivial zeros lie on the critical line $\Re(s) = 1/2$ --- is the central open
problem of analytic number theory. A recurrent theme of twentieth-century
mathematics is that such zeta functions have combinatorial and geometric avatars
whose Riemann Hypotheses are provable. The most celebrated is the family of zeta
functions of curves over finite fields, for which the Riemann Hypothesis is a
theorem (part of the Weil conjectures) and takes the form of the
Ramanujan--Petersson bound on Frobenius eigenvalues.

There is a beautiful discrete member of this family: the \emph{Ihara zeta
function} of a finite graph. It is defined by an Euler product over the graph's
\emph{prime geodesics} --- the equivalence classes of closed, tailless,
non-backtracking walks that are not powers of shorter walks --- in complete
analogy with the Euler product over primes. For a $(q+1)$-regular graph this
infinite product is a rational function, given by the \emph{Bass--Ihara
determinant formula}
\begin{equation}
\zeta_G(u)^{-1} = (1 - u^2)^{(n-1)(q-1)/2}\,\det\!\big(I - Au + q u^2 I\big),
\label{eq:bass}
\end{equation}
where $A$ is the adjacency matrix, $n$ the number of vertices, and every vertex
has degree $q+1$.

The number-theoretic content of \eqref{eq:bass} is controlled by the determinant
factor, which decomposes over the adjacency spectrum $\{\lambda_i\}_{i=1}^n$ into a
product of quadratic \emph{Euler factors} $p(\lambda, q, u) = 1 - \lambda u + q
u^2$, each of the elliptic-curve type $1 - aT + pT^2$. This paper isolates and
studies the resulting \emph{global spectral zeta}
\[
Z^{-1}(u) = \prod_{i=1}^{n} p(\lambda_i, q, u) = \det\!\big(I - Au + q u^2 I\big).
\]

Our central result is the following exact dichotomy.

\begin{theorem}[RH $\Leftrightarrow$ Ramanujan]\label{thm:main}
Let $q > 0$ and let $\lambda_1, \dots, \lambda_n \in \mathbb{R}$ be the spectrum.
Every zero $z$ of $Z^{-1}$ satisfies $|z| = 1/\sqrt{q}$ if and only if
$\lambda_i^2 \le 4q$ for every $i$.
\end{theorem}

\section{Definitions}

Throughout, $q$ is a positive parameter and the spectrum is a finite family
$\lambda : I \to \mathbb{C}$ indexed by a finite set $s$. We write $\|z\|$ for the
modulus of a complex number and $\Nm(z) = \|z\|^2$ for its squared modulus.

\begin{definition}[Local Euler factor]
For $\lambda, q, u \in \mathbb{C}$ the \emph{local factor} at $\lambda$ is
\[
p(\lambda, q, u) = 1 - \lambda u + q u^2.
\]
Its two roots (in $u$) multiply to $1/q$ and sum to $\lambda/q$; it matches the
Euler factor $1 - aT + pT^2$ of an elliptic curve, with $\lambda$ the analogue of
the trace of Frobenius and $q$ the analogue of the residue characteristic.
\end{definition}

\begin{definition}[Global spectral zeta]
For a finite index set $s$, spectrum $\lambda$, and parameters $q, u$,
\[
Z^{-1}_s(u) = \prod_{i \in s} p(\lambda_i, q, u).
\]
When $s$ ranges over all $n$ vertices this equals $\det(I - Au + qu^2 I)$.
\end{definition}

\begin{definition}[Critical circle and RH]
For $q > 0$ the \emph{critical circle} is $\{u : |u| = 1/\sqrt{q}\}$. We say
$Z^{-1}$ \emph{satisfies the Riemann Hypothesis} if every zero $z$ of $Z^{-1}$
lies on the critical circle.
\end{definition}

\begin{definition}[Ramanujan bound]
A real spectral value $\lambda$ satisfies the \emph{Ramanujan bound} if
$\lambda^2 \le 4q$, equivalently $|\lambda| \le 2\sqrt{q}$. A graph is a
\emph{Ramanujan graph} when every nontrivial adjacency eigenvalue satisfies it.
\end{definition}

\section{Structural properties}

\begin{proposition}[Normalization]\label{prop:norm}
For every finite $s$, spectrum $\lambda$, and $q$, one has $Z^{-1}_s(0) = 1$.
\end{proposition}
\begin{proof}
At $u = 0$ each factor is $p(\lambda_i, q, 0) = 1$, and the product of ones is
$1$.
\end{proof}

\begin{proposition}[Multiplicativity]\label{prop:mult}
If $s$ and $t$ are disjoint finite index sets, then
$Z^{-1}_{s \cup t}(u) = Z^{-1}_{s}(u)\cdot Z^{-1}_{t}(u)$.
\end{proposition}
\begin{proof}
Disjointness lets the product over $s \cup t$ split into the product over $s$
times the product over $t$.
\end{proof}

\begin{lemma}[Local functional equation]\label{lem:funeq}
For $q \neq 0$ and $u \neq 0$,
\[
q u^2 \cdot p\!\left(\lambda, q, \tfrac{1}{qu}\right) = p(\lambda, q, u).
\]
\end{lemma}
\begin{proof}
Substitute and clear denominators:
$q u^2\big(1 - \tfrac{\lambda}{qu} + \tfrac{1}{q u^2}\big)
= q u^2 - \lambda u + 1 = p(\lambda, q, u)$.
\end{proof}

\begin{theorem}[Global functional equation]\label{thm:funeq}
For a spectrum on a finite set $s$ with $n = |s|$, and $q \neq 0$, $u \neq 0$,
\[
(q u^2)^{n}\, Z^{-1}_s\!\left(\tfrac{1}{qu}\right) = Z^{-1}_s(u).
\]
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:funeq} factorwise and take the product over the $n$ indices;
the automorphy factors multiply to $(qu^2)^n$ and the remaining factors
reassemble into $Z^{-1}_s(u)$.
\end{proof}

The reflection $u \mapsto 1/(qu)$ is an involution whose fixed points satisfy
$u^2 = 1/q$, i.e.\ $|u| = 1/\sqrt{q}$: the critical circle is precisely the fixed
locus of the symmetry, mirroring the critical line $\Re(s) = 1/2$ fixed by
$s \mapsto 1-s$.

\section{The local Riemann Hypothesis}

\begin{theorem}[Local RH, squared form]\label{thm:local}
Let $\lambda, q \in \mathbb{R}$ with $q > 0$ and $\lambda^2 \le 4q$. If
$p(\lambda, q, z) = 0$ then $\Nm(z) = \|z\|^2 = 1/q$.
\end{theorem}
\begin{proof}
Write $z = x + iy$ and expand $1 - \lambda z + q z^2 = 0$ into real and imaginary
parts:
\[
1 - \lambda x + q(x^2 - y^2) = 0, \qquad -\lambda y + 2 q x y = 0.
\]
The imaginary equation gives $y = 0$ or $x = \lambda/(2q)$. If $y = 0$, the real
equation $q x^2 - \lambda x + 1 = 0$ has discriminant $\lambda^2 - 4q \le 0$, so a
real root exists only when $\lambda^2 = 4q$, where $x = \lambda/(2q)$ and
$x^2 = 1/q$. If $x = \lambda/(2q)$, substituting into the real equation gives
$q y^2 = 1 - \lambda^2/(4q)$, whence
\[
\Nm(z) = x^2 + y^2 = \frac{\lambda^2}{4q^2} + \frac{1}{q} - \frac{\lambda^2}{4q^2}
 = \frac{1}{q}.
\]
In all cases $\Nm(z) = 1/q$.
\end{proof}

\begin{theorem}[Off-circle root]\label{thm:off}
Let $\lambda, q \in \mathbb{R}$ with $q > 0$ and $\lambda^2 > 4q$. Then
$z = \dfrac{\lambda + \sqrt{\lambda^2 - 4q}}{2q}$ is a real root of
$p(\lambda, q, \cdot)$ with $\|z\| \neq 1/\sqrt{q}$.
\end{theorem}
\begin{proof}
With $\lambda^2 - 4q > 0$ the quadratic $q z^2 - \lambda z + 1 = 0$ has two
distinct real roots $z_\pm = (\lambda \pm \sqrt{\lambda^2 - 4q})/(2q)$ with product
$z_+ z_- = 1/q$. Being unequal, they cannot both equal $\pm 1/\sqrt{q}$; the
larger root $z_+$ satisfies $|z_+| > 1/\sqrt{q}$.
\end{proof}

\section{The global equivalence}

\begin{theorem}[Global RH: Ramanujan $\Rightarrow$ RH]\label{thm:global}
Let $q > 0$ and $\lambda_i^2 \le 4q$ for all $i \in s$. If $Z^{-1}_s(z) = 0$ then
$\|z\| = 1/\sqrt{q}$.
\end{theorem}
\begin{proof}
Since $\prod_{i \in s} p(\lambda_i, q, z) = 0$, some factor vanishes:
$p(\lambda_i, q, z) = 0$ for some $i \in s$. As $\lambda_i^2 \le 4q$,
Theorem~\ref{thm:local} gives $\Nm(z) = 1/q$, i.e.\ $\|z\| = 1/\sqrt{q}$.
\end{proof}

\begin{corollary}[Nonvanishing off the circle]\label{cor:nonvan}
Under the hypotheses of Theorem~\ref{thm:global}, if $\|z\| \neq 1/\sqrt{q}$ then
$Z^{-1}_s(z) \neq 0$.
\end{corollary}

\begin{theorem}[Converse]\label{thm:conv}
Let $q > 0$ and suppose some $i_0 \in s$ has $\lambda_{i_0}^2 > 4q$. Then there is
$z$ with $Z^{-1}_s(z) = 0$ and $\|z\| \neq 1/\sqrt{q}$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:off} the factor at $i_0$ has an off-circle root $z$. Since
$i_0 \in s$, this $z$ makes one factor of the product vanish, so
$Z^{-1}_s(z) = 0$.
\end{proof}

\begin{theorem}[RH $\Leftrightarrow$ Ramanujan]\label{thm:iff}
For $q > 0$ and real spectrum $\lambda$ on a finite set $s$,
\[
\big(\forall z,\ Z^{-1}_s(z) = 0 \Rightarrow \|z\| = \tfrac{1}{\sqrt{q}}\big)
\iff
\big(\forall i \in s,\ \lambda_i^2 \le 4q\big).
\]
\end{theorem}
\begin{proof}
($\Leftarrow$) is Theorem~\ref{thm:global}. ($\Rightarrow$) is the contrapositive
of Theorem~\ref{thm:conv}: an eigenvalue violating the bound yields an off-circle
zero, contradicting RH.
\end{proof}

This is the exact discrete counterpart of the equivalence, for curves over finite
fields, between the Riemann Hypothesis and the Hasse--Weil bound; here the
``curve'' is a network, the ``Frobenius eigenvalues'' are the adjacency
eigenvalues, and the Riemann Hypothesis is decidable by inspection of the
spectrum.

\section{Applications and future work}

\paragraph{Expander certification.} Ramanujan graphs are the optimal expanders,
foundational in error-correcting codes, pseudorandom generators, and
fault-tolerant networks. Theorem~\ref{thm:iff} recasts optimal expansion as an
analytic Riemann Hypothesis: to certify a network as an optimal expander it
suffices to confirm that the zeros of the explicit polynomial $Z^{-1}$ all lie on
the critical circle.

\paragraph{A provable model of the Weil RH.} The local factor
$1 - \lambda u + qu^2$ is literally the Euler factor of a curve, so the graph
theory furnishes an elementary, fully provable model of the Riemann Hypothesis
for curves over finite fields, with $|\lambda| \le 2\sqrt{q}$ playing the role of
$|a| \le 2\sqrt{p}$.

\paragraph{Future directions.} (1) Connect $Z^{-1}$ directly to
$\det(I - Au + qu^2 I)$ via the characteristic polynomial. (2) Incorporate the
$(1-u^2)^{(n-1)(q-1)/2}$ prefactor and prove the full Bass--Ihara identity
\eqref{eq:bass}. (3) Relate $u\,\frac{d}{du}\log Z_G(u)$ to closed geodesic counts
$N_m$ (a prime geodesic theorem). (4) Generalize to $\det(I - Au + Qu^2)$ for
irregular/weighted graphs. (5) Count zeros on the circle exactly using root
multiplicities. (6) Study factorization of $Z^{-1}$ under graph coverings.

