from __future__ import annotations
import cmath, math
from typing import Sequence, Tuple

def euler_factor(lam: complex, q: complex, u: complex) -> complex:
    """Local Bass-Ihara Euler factor 1 - lam*u + q*u^2."""
    return 1 - lam * u + q * u ** 2

def factor_roots(lam: float, q: float) -> Tuple[complex, complex]:
    """Roots (in u) of q u^2 - lam u + 1 = 0."""
    d = cmath.sqrt(lam ** 2 - 4 * q)
    return ((lam + d) / (2 * q), (lam - d) / (2 * q))

def demo() -> None:
    q = 4.0
    r = 1.0 / math.sqrt(q)
    print(f"critical radius 1/sqrt(q) = {r:.6f}")
    for lam in (-3.9, 0.0, 3.9, 5.0):
        z1, z2 = factor_roots(lam, q)
        tag = "on circle" if abs(abs(z1) - r) < 1e-9 else "OFF circle"
        print(f"lam={lam:+.2f}: |z1|={abs(z1):.5f} |z2|={abs(z2):.5f}  ({tag})")

if __name__ == "__main__":
    demo()

from __future__ import annotations
from typing import Sequence

def zeta_inv(spectrum: Sequence[complex], q: complex, u: complex) -> complex:
    """Global spectral zeta Z^-1(u) = prod_i (1 - lam_i u + q u^2)."""
    out: complex = 1 + 0j
    for lam in spectrum:
        out *= 1 - lam * u + q * u ** 2
    return out

def check_functional_equation(spectrum: Sequence[complex], q: complex,
                              u: complex) -> float:
    """Return |(q u^2)^n Z^-1(1/(qu)) - Z^-1(u)|."""
    n = len(spectrum)
    lhs = (q * u ** 2) ** n * zeta_inv(spectrum, q, 1 / (q * u))
    rhs = zeta_inv(spectrum, q, u)
    return abs(lhs - rhs)

if __name__ == "__main__":
    spec = [2.0, 0.7, -1.3, -0.4]
    for u in (0.3 + 0.2j, -0.15 + 0.4j, 0.5 - 0.1j):
        print(f"u={u}: residual={check_functional_equation(spec, 5.0, u):.2e}")

from __future__ import annotations
import cmath, math
from typing import Sequence

def is_ramanujan(spectrum: Sequence[float], q: float) -> bool:
    """Every eigenvalue satisfies lambda^2 <= 4q."""
    return all(lam ** 2 <= 4 * q + 1e-12 for lam in spectrum)

def all_zeros_on_circle(spectrum: Sequence[float], q: float) -> bool:
    """Check every root of every Euler factor lies on |z| = 1/sqrt(q)."""
    r = 1.0 / math.sqrt(q)
    for lam in spectrum:
        d = cmath.sqrt(lam ** 2 - 4 * q)
        for z in ((lam + d) / (2 * q), (lam - d) / (2 * q)):
            if abs(abs(z) - r) > 1e-7:
                return False
    return True

if __name__ == "__main__":
    tests = [
        ("Cycle C_6 (q=1)", [2*math.cos(2*math.pi*k/6) for k in range(6)], 1.0),
        ("Complete K_5 (q=3)", [4.0, -1.0, -1.0, -1.0, -1.0], 3.0),
        ("Non-expander (q=2)", [3.0, 4.0, -1.0, 0.5], 2.0),
    ]
    for name, spec, q in tests:
        print(f"{name}: Ramanujan={is_ramanujan(spec,q)}  "
              f"RH={all_zeros_on_circle(spec,q)}")

